<script>(function(){var url=@json(route('admin.updates.status')),seen=@json(($state['status']??'')==='running'),reload=false;function setBtn(b,a,r){if(!b)return;var i=b.querySelector('i'),t=document.getElementById('nodexa-update-button-text');b.disabled=r||!a;if(i)i.className=r?'fa fa-spinner fa-spin':(a?'fa fa-arrow-down':'fa fa-check');if(t)t.textContent=r?'Installerer…':(a?'Installer update':'Opdateret')}function poll(){fetch(url,{headers:{Accept:'application/json'},credentials:'same-origin'}).then(r=>r.json()).then(d=>{var s=d.state||{},a=d.update_available===true,log=document.getElementById('nodexa-update-log'),time=document.getElementById('nodexa-update-time'),btn=document.getElementById('nodexa-update-button'),title=document.getElementById('nuTitle'),msg=document.getElementById('nuMessage'),pill=document.getElementById('nuHeadText'),prog=document.getElementById('nuProgress'),icon=document.querySelector('#nuIcon i');if(log){log.textContent=d.log||'Ingen installationslog endnu.';log.scrollTop=log.scrollHeight}if(time)time.textContent=s.updated_at||'Ingen aktivitet endnu';if(s.status==='running'){seen=true;if(title)title.textContent='Installerer opdatering…';if(msg)msg.textContent=s.message||'Nodexa bliver opdateret. Lad siden være åben.';if(pill)pill.textContent='Opdaterer nu';if(prog)prog.classList.add('show');if(icon)icon.className='fa fa-refresh fa-spin';setBtn(btn,a,true);return}if(prog)prog.classList.remove('show');if(s.status==='failed'&&seen){if(title)title.textContent='Opdateringen kunne ikke installeres';if(msg)msg.textContent=s.message||'Kontrollér installationsloggen for detaljer.';if(pill)pill.textContent='Opdatering fejlede';if(icon)icon.className='fa fa-times';setBtn(btn,a,false);if(!reload){reload=true;setTimeout(()=>location.reload(),2500)}return}if(s.status==='success'&&seen){if(title)title.textContent='Nodexa er blevet opdateret';if(msg)msg.textContent=s.message||'Den nye version er installeret.';if(pill)pill.textContent='Update installeret';if(icon)icon.className='fa fa-check';setBtn(btn,false,false);if(!reload){reload=true;setTimeout(()=>location.reload(),2500)}return}if(title)title.textContent=a?'En ny version er klar':'Du kører den nyeste version';if(msg)msg.textContent=a?'Opdater Nodexa med ét klik. Din lokale konfiguration, serverdata og nodeopsætning bevares.':'Der er ingen nyere Nodexa-version tilgængelig på den valgte branch.';if(pill)pill.textContent=a?'Ny version tilgængelig':'Nodexa er opdateret';if(icon)icon.className=a?'fa fa-arrow-down':'fa fa-check';setBtn(btn,a,false)}).catch(()=>{})}setInterval(poll,2200);poll()})();</script>
